gOQ(){return"\u0633\u064a\u0633\u062a\u062e\u062f\u0645\u0648\u0646\u0647 \u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u2014 \u0644\u0627 \u064a\u0645\u0643\u0646 \u0625\u0646\u0634\u0627\u0624\u0647\u0645 \u0628\u062f\u0648\u0646\u0647."},
gOL(){return"\u0627\u0644\u062f\u0648\u0631"},
gOP(){return"\u0641\u0631\u064a\u0642 \u0627\u0644\u0645\u0628\u064a\u0639\u0627\u062a"},
